:root{--primary:#1b8168;--on-primary:#fff;--primary-fg:#117b63;--primary-soft:#dcf5ec;--accent:#a9c24f;--accent-soft:#eaf2ce;--accent-fg:#56701f;--cream:#f4f8f0;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;--teal-soft:#d9ecec;--danger:#b23b3b;--danger-soft:#f6e4e2;}
*{box-sizing:border-box} body{background:#e7ede4;font-family:Figtree,'Segoe UI',system-ui,sans-serif;color:var(--ink);margin:0}
.phone{width:390px;margin:16px auto;background:var(--cream);border-radius:28px;overflow:hidden;box-shadow:0 8px 30px rgb(0 0 0/.12);padding-bottom:24px;position:relative;min-height:760px}
.top{display:flex;align-items:center;gap:8px;padding:14px 20px;font-size:14px;color:var(--ink-soft)}
.back{color:var(--primary-fg);font-weight:700;text-decoration:none}
h1,h2,h3{font-family:'Bricolage Grotesque','Segoe UI',sans-serif;margin:0}
h1{font-size:28px;padding:4px 20px 0} h2{font-size:22px}
.sub{padding:2px 20px 0;color:var(--ink-soft);font-size:14px}
.card{background:var(--paper);border:1px solid var(--line);border-radius:24px;padding:16px;margin:16px 20px 0}
.owner{display:flex;align-items:center;gap:12px;padding:8px 20px 0}
.av{width:48px;height:48px;border-radius:50%;background:var(--primary-soft);color:var(--primary-fg);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:18px;flex-shrink:0}
.av.sm{width:40px;height:40px;font-size:15px}
.next{display:flex;gap:12px;align-items:center}
.tile{width:56px;border-radius:16px;background:var(--primary);color:#fff;text-align:center;padding:6px 0;flex-shrink:0}
.tile b{display:block;font-size:22px;line-height:1} .tile small{font-size:11px;text-transform:uppercase}
.kicker{font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--accent-fg)}
.btn{display:flex;align-items:center;justify-content:center;min-height:44px;border-radius:999px;font-weight:800;font-size:15px;border:0;padding:0 18px;cursor:pointer;text-decoration:none}
.btn.primary{background:var(--primary);color:var(--on-primary)} .btn.ghost{background:transparent;border:1.5px solid var(--line);color:var(--ink)}
.row{display:flex;gap:8px;margin-top:12px} .row .btn{flex:1}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:12px 20px 0;padding:0;list-style:none}
.ic{background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:10px;display:flex;flex-direction:column;cursor:pointer}
.ph{aspect-ratio:1;border-radius:12px;background:linear-gradient(135deg,#dfe9db,#cfe0c9);display:flex;align-items:center;justify-content:center;color:var(--ink-soft);font-size:24px}
.ic b{font-size:13px;margin-top:8px} .ic small{font-size:11px;color:var(--ink-soft)}
.mode{margin-top:8px;border-radius:12px;text-align:center;padding:6px 4px;font-size:12px;font-weight:800}
.mode.gift{background:var(--accent-soft);color:var(--accent-fg)} .mode.swap{background:var(--teal-soft);color:#2d6e70}
.tabs{display:flex;gap:6px;margin:16px 20px 0} .tab{border-radius:999px;padding:8px 14px;font-size:13px;font-weight:700;border:1.5px solid var(--line);background:var(--paper)} .tab.on{background:var(--ink);color:#fff;border-color:var(--ink)}
.pill{margin-left:auto;border-radius:999px;padding:3px 9px;font-size:11px;font-weight:800}
.pill.org{background:var(--accent-soft);color:var(--accent-fg);text-transform:uppercase;letter-spacing:.08em} .pill.me{background:var(--primary-soft);color:var(--primary-fg)}
.plist{list-style:none;margin:12px 20px 0;padding:0 14px;background:var(--paper);border:1px solid var(--line);border-radius:24px}
.plist>li{padding:12px 0;border-bottom:1px solid var(--line)} .plist>li:last-child{border:0}
.ph-row{display:flex;align-items:center;gap:12px}
.items{margin-left:52px} .it{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--line);text-decoration:none;color:var(--ink)}
.th{width:48px;height:48px;border-radius:12px;background:linear-gradient(135deg,#dfe9db,#cfe0c9);flex-shrink:0;display:inline-block}
.it span{flex:1;font-size:15px} .it small{display:block;font-size:12px;color:var(--ink-soft)}
.more{display:inline-flex;align-items:center;min-height:44px;font-weight:800;font-size:14px;color:var(--primary-fg);text-decoration:none}
.hero{height:300px;background:linear-gradient(135deg,#cfe0c9,#b9d1b2);display:flex;align-items:center;justify-content:center;font-size:56px;color:#7d977a}
.ctx{display:flex;gap:10px;align-items:center;background:var(--primary-soft);border-radius:16px;padding:10px 12px;font-size:13px;color:var(--primary-fg);font-weight:700}
.ctx.warn{background:var(--danger-soft);color:var(--danger)} .ctx.muted,.muted{background:#eef2ec;color:var(--ink-soft)}
.hint{font-size:13px;color:var(--ink-soft);margin-top:8px}
.scrim{position:absolute;inset:0;background:rgb(20 28 24/.55);display:flex;align-items:flex-end}
.sheet{background:var(--paper);border-radius:24px 24px 0 0;padding:20px;width:100%}
.opt{display:flex;align-items:center;gap:12px;padding:10px;border:1.5px solid var(--line);border-radius:16px;margin-top:8px} .opt.on{border-color:var(--primary);background:var(--primary-soft)}
.status{display:inline-block;border-radius:999px;padding:4px 10px;font-size:12px;font-weight:800;background:var(--primary-soft);color:var(--primary-fg)}
.chip{display:inline-block;border-radius:12px;padding:4px 10px;font-size:12px;font-weight:800}

